  ('cmp-5','Вектор Логистик','Новосибирск','Логистика',4.4,'Региональный оператор B2B-доставки и складского сопровождения.','Компания развивает сеть маршрутов по Сибири и ищет новых корпоративных клиентов и подрядчиков.','["Склад", "Доставка", "B2B"]'::jsonb,'[{"id":"r5","author":"СибПромСнаб","text":"Быстро запускают новые маршруты и держат сроки."}]'::jsonb),
  ('cmp-6','СибПромСнаб','Омск','Снабжение',4.7,'Комплексные поставки оборудования, крепежа и расходных материалов для производств.','Работает с производственными площадками по всей Сибири, формирует пул надежных поставщиков.','["Снабжение", "Опт", "Промышленность"]'::jsonb,'[{"id":"r6","author":"Вектор Логистик","text":"Понятные условия и стабильные объемы."}]'::jsonb),
  ('cmp-7','Digital North','Санкт-Петербург','Digital',4.9,'Агентство digital-маркетинга и web-разработки для B2B-компаний.','Ведет проекты по лидогенерации, сайтам и performance-маркетингу для производственных и сервисных компаний.','["Performance", "Сайты", "Лидогенерация"]'::jsonb,'[{"id":"r7","author":"Город Пекарен","text":"Сильная команда и хороший темп работы."}]'::jsonb),
  ('cmp-8','ПромМеталл Групп','Пермь','Металлообработка',4.6,'Производство металлоконструкций и серийных комплектующих для бизнеса.','Компания закрывает заказы на металлоконструкции, сварку и комплексную обработку под B2B-проекты.','["Металлоконструкции", "Производство", "Сварка"]'::jsonb,'[{"id":"r8","author":"УралСнаб","text":"Надежный производственный партнер на регулярные поставки."}]'::jsonb),
  ('cmp-9','ФудПак Сервис','Самара','Упаковка',4.5,'Поставки пищевой и транспортной упаковки для сетевого бизнеса.','Работает с кафе, ритейлом и производителями, быстро собирает партии под регулярные поставки.','["Упаковка", "HoReCa", "Ритейл"]'::jsonb,'[{"id":"r9","author":"North Beans","text":"Оперативно отвечают и держат качество продукции."}]'::jsonb),
  ('cmp-10','СтройКонтур','Уфа','Строительство',4.3,'Подрядчик по коммерческой отделке и инженерным работам.','Берет объекты под офисы, торговые точки и производственные помещения, работает поэтапно и прозрачно.','["Отделка", "Коммерческие объекты", "Инженерия"]'::jsonb,'[{"id":"r10","author":"ПромМеталл Групп","text":"Удобно работать по сметам и этапам."}]'::jsonb),
  ('cmp-11','Cloud Office Pro','Москва','IT услуги',4.8,'Интегратор облачной инфраструктуры, связи и корпоративных сервисов.','Помогает компаниям строить IT-инфраструктуру, переносить сервисы в облако и поддерживать рабочие места.','["IT-инфраструктура", "Облака", "Поддержка"]'::jsonb,'[{"id":"r11","author":"ТехноПласт","text":"Сильная экспертиза и понятные коммерческие предложения."}]'::jsonb),
  ('cmp-12','Ритейл Аналитика','Екатеринбург','Консалтинг',4.4,'Аналитика продаж, ассортиментное планирование и BI для торговых компаний.','Команда внедряет отчеты, дашборды и модели планирования для сетей и франшиз.','["BI", "Аналитика", "Ритейл"]'::jsonb,'[{"id":"r12","author":"Город Пекарен","text":"Хорошо понимают задачи сетевого бизнеса."}]'::jsonb);
